package com.reviewflow.security;
import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.*;
@Service public class JwtService { private final String secret; private final ObjectMapper json=new ObjectMapper(); public JwtService(@Value("${app.jwt-secret:development-secret-change-me-please}") String s){secret=s;} private String b64(byte[] b){return Base64.getUrlEncoder().withoutPadding().encodeToString(b);} public String issue(UUID userId){try{String h=b64("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes());String p=b64(json.writeValueAsBytes(Map.of("sub",userId.toString(),"exp",Instant.now().plusSeconds(86400*7).getEpochSecond())));return h+"."+p+"."+sign(h+"."+p);}catch(Exception e){throw new IllegalStateException(e);}} public UUID verify(String token){try{String[] p=token.split("\\.");if(p.length!=3||!sign(p[0]+"."+p[1]).equals(p[2]))return null;Map<?,?> claims=json.readValue(Base64.getUrlDecoder().decode(p[1]),Map.class);if(((Number)claims.get("exp")).longValue()<Instant.now().getEpochSecond())return null;return UUID.fromString((String)claims.get("sub"));}catch(Exception e){return null;}} private String sign(String text)throws Exception{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return b64(mac.doFinal(text.getBytes(StandardCharsets.UTF_8)));} }
